-- MySQL 8.0.16+ / InnoDB / FK=1. 실제 MySQL 실행·COMMIT·배포 검증은 수행하지 않았다.
SET NAMES utf8mb4;
SELECT @@GLOBAL.server_uuid AS server_uuid, DATABASE() AS schema_name;
SET @ci_environment=NULL; -- 'DEVELOPMENT' 또는 'PRODUCTION'
SET @ci_expected_server_uuid=NULL; -- 해당 환경에서 승인한 실제 UUID
SET @ci_expected_schema=NULL; -- 해당 환경의 실제 schema
SET @ci_actor=NULL; -- 실제 적용자 로그인 ID(비밀번호 아님)
SET @ci_mode=NULL; -- 'FIRST_INSTALL' 또는 'UPGRADE', 자동 선택하지 않는다.
SET @ci_previous_template_id=NULL; -- UPGRADE에서만: 현재 ACTIVE의 정확한 ID
SET @ci_previous_version=NULL; -- UPGRADE에서만: 현재 ACTIVE의 버전(8 미만)
SET @ci_previous_marker=NULL; -- UPGRADE에서만: 현재 ACTIVE의 tmplt_expn 전체
SET @ci_model='DRAFT_C_STRUCTURE',@ci_version=8;
SET @ci_marker='row-delete-v8-20261026; payload=ae1d7b2201db3d1f4929a018e7eb1dfe075c0f3e00c4900f97bfc3308a6cea13';
SET @ci_name='2026-10-26 Model Input editor v8';
SET @ci_ok=0,@ci_verified=0,@ci_new=NULL;
SET @ci_expected_template_id=NULL; -- 등록 COMMIT 후 새 연결에서 확인한 이 환경의 v8 DRAFT ID
SET @ci_reader_ready=0; -- 해당 환경의 최신 v8 호환 코드 확인 후에만 1
SET @ci_retired=0,@ci_activated=0,@ci_published=0;

-- 1. 등록과 같은 최종 metadata/수정 범위 및 전체 qry 원문의 SHA-256.
