-- 2. 같은 모델과 대상 참조를 잠근다. FIRST_INSTALL도 등록 COMMIT 후 DRAFT 하나가 있어야 한다.
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
START TRANSACTION;
SELECT tmplt_id,mdl_spt_cd,tmplt_ver_no,tmplt_stat_cd FROM tmd_mdl_inpttmpltm
WHERE mdl_spt_cd=@ci_model FOR UPDATE;
SET @ci_existing=(SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE mdl_spt_cd=@ci_model);
SET @ci_new=(SELECT tmplt_id FROM tmd_mdl_inpttmpltm WHERE tmplt_id=@ci_expected_template_id
 AND CAST(mdl_spt_cd AS BINARY)=CAST(@ci_model AS BINARY) AND tmplt_ver_no=@ci_version AND tmplt_stat_cd='DRAFT'
 AND aply_bgn_dtm IS NULL AND CAST(tmplt_expn AS BINARY)=CAST(@ci_marker AS BINARY)
 AND CAST(tmplt_ver_nm AS BINARY)=CAST(@ci_name AS BINARY) AND del_yn='N');
SET @ci_previous_time=(SELECT aply_bgn_dtm FROM tmd_mdl_inpttmpltm WHERE tmplt_id=@ci_previous_template_id);
SELECT inpt_file_id FROM tmd_mdl_inptfiled WHERE tmplt_id=@ci_new FOR SHARE;
SELECT s.inpt_sht_id FROM tmd_mdl_inptshtd s JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id=@ci_new FOR SHARE;
SELECT b.inpt_tbl_id FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id=@ci_new FOR SHARE;
SELECT m.mod_scop_id FROM tmd_mdl_inptmodscopd m JOIN tmd_mdl_inpttbld b USING(inpt_tbl_id) JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id=@ci_new FOR SHARE;
SELECT case_id FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id IN (@ci_previous_template_id,@ci_new) FOR SHARE;
SET @ci_previous_cases=(SELECT COUNT(*) FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id=@ci_previous_template_id);
SELECT drft_id FROM tmd_mdl_inptdrftm WHERE tmplt_id IN (@ci_previous_template_id,@ci_new) FOR SHARE;
SET @ci_previous_drafts=(SELECT COUNT(*) FROM tmd_mdl_inptdrftm WHERE tmplt_id=@ci_previous_template_id);
SELECT upld_file_id FROM tmd_mdl_inptupldfiled WHERE tmplt_id IN (@ci_previous_template_id,@ci_new) FOR SHARE;
SET @ci_previous_uploads=(SELECT COUNT(*) FROM tmd_mdl_inptupldfiled WHERE tmplt_id=@ci_previous_template_id);
SELECT base_id FROM tmd_mdl_inptbasem WHERE tmplt_id IN (@ci_previous_template_id,@ci_new) FOR SHARE;
SET @ci_previous_baselines=(SELECT COUNT(*) FROM tmd_mdl_inptbasem WHERE tmplt_id=@ci_previous_template_id);
SET @ci_ok=IF(COALESCE(CAST(@ci_environment AS BINARY) IN ('DEVELOPMENT','PRODUCTION'),0)=1
 AND COALESCE(CAST(@@GLOBAL.server_uuid AS BINARY)=CAST(@ci_expected_server_uuid AS BINARY),0)=1
 AND COALESCE(CAST(DATABASE() AS BINARY)=CAST(@ci_expected_schema AS BINARY),0)=1
 AND @@GLOBAL.read_only=0 AND @@GLOBAL.super_read_only=0 AND @@SESSION.foreign_key_checks=1
 AND @ci_actor IS NOT NULL AND REGEXP_LIKE(CONVERT(@ci_actor USING utf8mb4) COLLATE utf8mb4_bin,_utf8mb4'^[a-zA-Z0-9._@-]{1,50}$','c')
 AND @ci_reader_ready=1 AND @ci_expected_template_id IS NOT NULL AND @ci_new IS NOT NULL
 AND ((CAST(@ci_mode AS BINARY)='FIRST_INSTALL' AND @ci_existing=1
   AND @ci_previous_template_id IS NULL AND @ci_previous_version IS NULL AND @ci_previous_marker IS NULL
   AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE mdl_spt_cd=@ci_model AND tmplt_stat_cd='ACTIVE' AND del_yn='N')=0)
 OR (CAST(@ci_mode AS BINARY)='UPGRADE' AND @ci_previous_template_id IS NOT NULL
   AND @ci_previous_version<@ci_version AND @ci_previous_marker IS NOT NULL
   AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE mdl_spt_cd=@ci_model AND tmplt_stat_cd='ACTIVE' AND del_yn='N')=1
   AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE tmplt_id=@ci_previous_template_id
    AND CAST(mdl_spt_cd AS BINARY)=CAST(@ci_model AS BINARY) AND tmplt_ver_no=@ci_previous_version
    AND tmplt_stat_cd='ACTIVE' AND aply_bgn_dtm IS NOT NULL
    AND CAST(tmplt_expn AS BINARY)=CAST(@ci_previous_marker AS BINARY) AND del_yn='N')=1))
 AND NOT EXISTS(SELECT 1 FROM tmd_mdl_inpttmpltm WHERE mdl_spt_cd=@ci_model AND tmplt_ver_no>@ci_version)
 AND NOT EXISTS(SELECT 1 FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id=@ci_new)
 AND NOT EXISTS(SELECT 1 FROM tmd_mdl_inptdrftm WHERE tmplt_id=@ci_new)
 AND NOT EXISTS(SELECT 1 FROM tmd_mdl_inptupldfiled WHERE tmplt_id=@ci_new)
 AND NOT EXISTS(SELECT 1 FROM tmd_mdl_inptbasem WHERE tmplt_id=@ci_new)
,1,0);
SELECT IF(@ci_ok=1,'PRECHECK_OK','STOP_AND_ROLLBACK') AS decision,
 @ci_mode AS publication_mode,@ci_previous_template_id AS previous_active_id,@ci_new AS exact_draft_id;
-- Exact natural-key metadata and full qry bytes (or their SHA-256), not counts alone.
SET @ci_files_count=(SELECT COUNT(*) FROM tmd_mdl_inptfiled WHERE tmplt_id=@ci_new);
SET @ci_files_match=(SELECT COUNT(*) FROM JSON_TABLE(@ci_files,'$[*]' COLUMNS(
 role VARCHAR(20) PATH '$[0]',name VARCHAR(255) PATH '$[1]',ord INT PATH '$[2]',kind VARCHAR(20) PATH '$[3]')) x
 JOIN tmd_mdl_inptfiled f ON f.tmplt_id=@ci_new AND CAST(f.mdl_file_cd AS BINARY)=CAST(x.role AS BINARY)
 WHERE CAST(f.file_nm AS BINARY)=CAST(x.name AS BINARY) AND f.file_ord=x.ord AND CAST(f.file_type_cd AS BINARY)=CAST(x.kind AS BINARY)
 AND f.file_strt_hash_val IS NULL AND f.del_yn='N');
SET @ci_sheets_count=(SELECT COUNT(*) FROM tmd_mdl_inptshtd s JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id=@ci_new);
SET @ci_sheets_match=(SELECT COUNT(*) FROM JSON_TABLE(@ci_sheets,'$[*]' COLUMNS(
 role VARCHAR(20) PATH '$[0]',name VARCHAR(150) PATH '$[1]',ord INT PATH '$[2]',state VARCHAR(20) PATH '$[3]')) x
 JOIN tmd_mdl_inptfiled f ON f.tmplt_id=@ci_new AND CAST(f.mdl_file_cd AS BINARY)=CAST(x.role AS BINARY)
 JOIN tmd_mdl_inptshtd s ON s.inpt_file_id=f.inpt_file_id AND CAST(s.sht_nm AS BINARY)=CAST(x.name AS BINARY)
 WHERE s.sht_ord=x.ord AND CAST(s.sht_stat_cd AS BINARY)=CAST(x.state AS BINARY) AND s.del_yn='N');
SET @ci_tables_count=(SELECT COUNT(*) FROM tmd_mdl_inpttbld b JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id=@ci_new);
SET @ci_tables_match=(SELECT COUNT(*) FROM JSON_TABLE(@ci_tables,'$[*]' COLUMNS(
 role VARCHAR(20) PATH '$[0]',
 sheet VARCHAR(150) PATH '$[1]',
 name VARCHAR(100) PATH '$[2]',
 ord INT PATH '$[3]',
 br INT PATH '$[4]',
 er INT PATH '$[5]',
 bc INT PATH '$[6]',
 ec INT PATH '$[7]',
 hr INT PATH '$[8]',
 he INT PATH '$[9]',
 dr INT PATH '$[10]',
 ra CHAR(1) PATH '$[11]',
 ca CHAR(1) PATH '$[12]',
 description VARCHAR(500) PATH '$[13]',
 qry LONGTEXT PATH '$[14]')) x
 JOIN tmd_mdl_inptfiled f ON f.tmplt_id=@ci_new AND CAST(f.mdl_file_cd AS BINARY)=CAST(x.role AS BINARY)
 JOIN tmd_mdl_inptshtd s ON s.inpt_file_id=f.inpt_file_id AND CAST(s.sht_nm AS BINARY)=CAST(x.sheet AS BINARY)
 JOIN tmd_mdl_inpttbld b ON b.inpt_sht_id=s.inpt_sht_id AND CAST(b.inpt_tbl_nm AS BINARY)=CAST(x.name AS BINARY)
 WHERE b.tbl_ord=x.ord AND b.tbl_bgn_row_no=x.br AND b.tbl_end_row_no=x.er
 AND b.tbl_bgn_col_no=x.bc AND b.tbl_end_col_no=x.ec AND b.hdr_bgn_row_no=x.hr
 AND b.hdr_end_row_no=x.he AND b.data_bgn_row_no=x.dr AND b.row_add_psbl_yn=x.ra
 AND b.col_add_psbl_yn=x.ca AND (CAST(b.inpt_tbl_expn AS BINARY) <=> CAST(NULLIF(x.description,'') AS BINARY))
 AND SHA2(b.qry_json,256)=x.qry AND b.del_yn='N');
SET @ci_scopes_count=(SELECT COUNT(*) FROM tmd_mdl_inptmodscopd m JOIN tmd_mdl_inpttbld b USING(inpt_tbl_id) JOIN tmd_mdl_inptshtd s USING(inpt_sht_id) JOIN tmd_mdl_inptfiled f USING(inpt_file_id) WHERE f.tmplt_id=@ci_new);
SET @ci_scopes_match=(SELECT COUNT(*) FROM JSON_TABLE(@ci_scopes,'$[*]' COLUMNS(
 role VARCHAR(20) PATH '$[0]',sheet VARCHAR(150) PATH '$[1]',name VARCHAR(100) PATH '$[2]',ord INT PATH '$[3]',br INT PATH '$[4]',er INT PATH '$[5]',bc INT PATH '$[6]',ec INT PATH '$[7]')) x
 JOIN tmd_mdl_inptfiled f ON f.tmplt_id=@ci_new AND CAST(f.mdl_file_cd AS BINARY)=CAST(x.role AS BINARY)
 JOIN tmd_mdl_inptshtd s ON s.inpt_file_id=f.inpt_file_id AND CAST(s.sht_nm AS BINARY)=CAST(x.sheet AS BINARY)
 JOIN tmd_mdl_inpttbld b ON b.inpt_sht_id=s.inpt_sht_id AND CAST(b.inpt_tbl_nm AS BINARY)=CAST(x.name AS BINARY)
 JOIN tmd_mdl_inptmodscopd m ON m.inpt_tbl_id=b.inpt_tbl_id AND m.mod_scop_ord=x.ord
 WHERE m.bgn_row_no=x.br AND m.end_row_no=x.er AND m.bgn_col_no=x.bc AND m.end_col_no=x.ec AND m.del_yn='N');
SET @ci_verified=IF(@ci_ok=1 AND @ci_new IS NOT NULL
 AND @ci_files_count=4 AND @ci_files_match=4 AND @ci_sheets_count=70 AND @ci_sheets_match=70
 AND @ci_tables_count=96 AND @ci_tables_match=96 AND @ci_scopes_count=171 AND @ci_scopes_match=171,1,0);
SELECT @ci_new AS target_template_id,@ci_files_match AS files_must_be_4,
 @ci_sheets_match AS sheets_must_be_70,@ci_tables_match AS tables_must_be_96,
 @ci_scopes_match AS scopes_must_be_171,@ci_verified AS verified_must_be_1;

-- 3. 같은 transaction에서 지정한 기존 ACTIVE만 DEPRECATED로 전환하고 검증한 v8만 발행한다.
SET @ci_time=CURRENT_TIMESTAMP(6);
UPDATE tmd_mdl_inpttmpltm SET tmplt_stat_cd='DEPRECATED',mod_usr_logn_id=@ci_actor,mod_dtm=CURRENT_TIMESTAMP
WHERE @ci_verified=1 AND CAST(@ci_mode AS BINARY)='UPGRADE' AND tmplt_id=@ci_previous_template_id
 AND CAST(mdl_spt_cd AS BINARY)=CAST(@ci_model AS BINARY) AND tmplt_ver_no=@ci_previous_version
 AND tmplt_stat_cd='ACTIVE' AND aply_bgn_dtm=@ci_previous_time
 AND CAST(tmplt_expn AS BINARY)=CAST(@ci_previous_marker AS BINARY) AND del_yn='N';
-- 직전 명령의 처리 건수가 아닌, 잠근 행의 정확한 전환 후 상태를 검증한다.
SET @ci_retired=(SELECT COUNT(*) FROM tmd_mdl_inpttmpltm
 WHERE @ci_verified=1 AND CAST(@ci_mode AS BINARY)='UPGRADE' AND tmplt_id=@ci_previous_template_id
 AND CAST(mdl_spt_cd AS BINARY)=CAST(@ci_model AS BINARY) AND tmplt_ver_no=@ci_previous_version
 AND tmplt_stat_cd='DEPRECATED' AND aply_bgn_dtm=@ci_previous_time
 AND CAST(tmplt_expn AS BINARY)=CAST(@ci_previous_marker AS BINARY) AND CAST(mod_usr_logn_id AS BINARY)=CAST(@ci_actor AS BINARY) AND del_yn='N');
UPDATE tmd_mdl_inpttmpltm SET tmplt_stat_cd='ACTIVE',aply_bgn_dtm=@ci_time,mod_usr_logn_id=@ci_actor,mod_dtm=CURRENT_TIMESTAMP
WHERE @ci_verified=1 AND ((CAST(@ci_mode AS BINARY)='UPGRADE' AND @ci_retired=1)
 OR (CAST(@ci_mode AS BINARY)='FIRST_INSTALL' AND @ci_retired=0))
 AND tmplt_id=@ci_new AND CAST(mdl_spt_cd AS BINARY)=CAST(@ci_model AS BINARY) AND tmplt_ver_no=@ci_version
 AND tmplt_stat_cd='DRAFT' AND aply_bgn_dtm IS NULL
 AND CAST(tmplt_expn AS BINARY)=CAST(@ci_marker AS BINARY) AND CAST(tmplt_ver_nm AS BINARY)=CAST(@ci_name AS BINARY) AND del_yn='N';
SET @ci_activated=(SELECT COUNT(*) FROM tmd_mdl_inpttmpltm
 WHERE @ci_verified=1 AND ((CAST(@ci_mode AS BINARY)='UPGRADE' AND @ci_retired=1)
 OR (CAST(@ci_mode AS BINARY)='FIRST_INSTALL' AND @ci_retired=0))
 AND tmplt_id=@ci_new AND CAST(mdl_spt_cd AS BINARY)=CAST(@ci_model AS BINARY) AND tmplt_ver_no=@ci_version
 AND tmplt_stat_cd='ACTIVE' AND aply_bgn_dtm=@ci_time
 AND CAST(tmplt_expn AS BINARY)=CAST(@ci_marker AS BINARY) AND CAST(tmplt_ver_nm AS BINARY)=CAST(@ci_name AS BINARY)
 AND CAST(mod_usr_logn_id AS BINARY)=CAST(@ci_actor AS BINARY) AND del_yn='N');
SET @ci_published=IF(@ci_verified=1 AND @ci_activated=1
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE tmplt_id=@ci_new
  AND CAST(mdl_spt_cd AS BINARY)=CAST(@ci_model AS BINARY) AND tmplt_ver_no=@ci_version
  AND tmplt_stat_cd='ACTIVE' AND aply_bgn_dtm=@ci_time AND CAST(tmplt_expn AS BINARY)=CAST(@ci_marker AS BINARY)
  AND CAST(tmplt_ver_nm AS BINARY)=CAST(@ci_name AS BINARY) AND CAST(mod_usr_logn_id AS BINARY)=CAST(@ci_actor AS BINARY) AND del_yn='N')=1
 AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE mdl_spt_cd=@ci_model AND tmplt_stat_cd='ACTIVE' AND del_yn='N')=1
 AND ((CAST(@ci_mode AS BINARY)='FIRST_INSTALL' AND @ci_retired=0)
  OR (CAST(@ci_mode AS BINARY)='UPGRADE' AND @ci_retired=1
   AND (SELECT COUNT(*) FROM tmd_mdl_inpttmpltm WHERE tmplt_id=@ci_previous_template_id
    AND CAST(mdl_spt_cd AS BINARY)=CAST(@ci_model AS BINARY) AND tmplt_ver_no=@ci_previous_version
    AND tmplt_stat_cd='DEPRECATED' AND aply_bgn_dtm=@ci_previous_time
    AND CAST(tmplt_expn AS BINARY)=CAST(@ci_previous_marker AS BINARY) AND CAST(mod_usr_logn_id AS BINARY)=CAST(@ci_actor AS BINARY) AND del_yn='N')=1))
 AND (SELECT COUNT(*) FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id=@ci_previous_template_id)=@ci_previous_cases
 AND NOT EXISTS(SELECT 1 FROM tmd_mdl_scnrcasetmpltd WHERE tmplt_id=@ci_new)
 AND (SELECT COUNT(*) FROM tmd_mdl_inptdrftm WHERE tmplt_id=@ci_previous_template_id)=@ci_previous_drafts
 AND NOT EXISTS(SELECT 1 FROM tmd_mdl_inptdrftm WHERE tmplt_id=@ci_new)
 AND (SELECT COUNT(*) FROM tmd_mdl_inptupldfiled WHERE tmplt_id=@ci_previous_template_id)=@ci_previous_uploads
 AND NOT EXISTS(SELECT 1 FROM tmd_mdl_inptupldfiled WHERE tmplt_id=@ci_new)
 AND (SELECT COUNT(*) FROM tmd_mdl_inptbasem WHERE tmplt_id=@ci_previous_template_id)=@ci_previous_baselines
 AND NOT EXISTS(SELECT 1 FROM tmd_mdl_inptbasem WHERE tmplt_id=@ci_new)
,1,0);
SELECT @ci_retired AS retired_rows,@ci_activated AS activated_rows,@ci_published AS published_must_be_1,
 IF(@ci_published=1,'VERIFIED_PUBLISHED','STOP_AND_ROLLBACK') AS decision;
SELECT tmplt_id,mdl_spt_cd,tmplt_ver_no,tmplt_stat_cd,aply_bgn_dtm,tmplt_expn FROM tmd_mdl_inpttmpltm
WHERE tmplt_id IN (@ci_previous_template_id,@ci_new) ORDER BY tmplt_ver_no;
-- published_must_be_1=1 / VERIFIED_PUBLISHED인 실제 실행만 마지막 ROLLBACK 대신 같은 연결에서 COMMIT 선택.
ROLLBACK;
-- 등록과 발행은 별도 transaction이다. 발행 예행은 등록한 DRAFT를 지우지 않는다.
-- COMMIT 후 새 연결에서 실제 서버/schema/ID/marker/ACTIVE1개와 기존 참조 보존을 재확인한다.
-- 기존 Case/Draft/업로드/공유 기준의 양식 연결과 파일은 변경하지 않는다. 새 Case/업로드부터 새 ACTIVE를 사용한다.
-- 발행 뒤 문제는 접수/소비를 비활성화하고 증거·이력·양식을 보존해 조사한다. 이전 양식 재활성화/삭제는 자동 수행하지 않는다.
-- Implementation readiness: ready for manual rehearsal after compatible deployment; 실제 MySQL 예행/COMMIT/API는 미검증.
